from pathlib import Path
import pandas as pd,numpy as np,json
O=Path('outputs');d=pd.read_csv(O/'stage6_rbm6_gnomad_aligned.csv');q=pd.read_csv(O/'stage6_rbm6_gtex_cortex_region.tsv',sep='\t');q=q[(q.se>0)&q.ref.isin(['A','C','G','T'])&q.alt.isin(['A','C','G','T'])].copy();q['pair']=q.apply(lambda r:''.join(sorted([r.ref,r.alt])),axis=1);dups=q[q.duplicated(['position','pair'],keep=False)];assert all(len(g[['beta','se','ac','an']].drop_duplicates())==1 for _,g in dups.groupby(['position','pair']));q=q.drop_duplicates(['position','pair']);x=d.merge(q,left_on=['pos','pair'],right_on=['position','pair'],suffixes=('','_qtl'),validate='one_to_one');x['qtl_beta_anchor']=np.where(x.alt_qtl==x.anchor_effect_allele,x.beta,-x.beta);x['qtl_z_anchor']=x.qtl_beta_anchor/x.se;x['qtl_anchor_af']=np.where(x.alt_qtl==x.anchor_effect_allele,x.ac/x.an,1-x.ac/x.an);x['qtl_ref_af_diff']=abs(x.qtl_anchor_af-x.nfe_anchor_af);n=len(x);x=x[x.qtl_ref_af_diff<=.2].copy();assert x.rs.is_unique;x.to_csv(O/'stage6_rbm6_gtex_cortex_aligned.csv',index=False);rec={'source_valid_nonpal_snv_unique':len(q),'matched_before_af':n,'matched_after_af':len(x),'af_filter_excluded':n-len(x),'mean_af_diff':float(x.qtl_ref_af_diff.mean()),'max_af_diff':float(x.qtl_ref_af_diff.max()),'contains_original_marker':bool(x.rs.eq('rs2353586').any()),'contains_hfrs_marker':bool(x.rs.eq('rs2282749').any()),'qtl_sample_size':205,'source_beta_effect_allele':'GRCh38 ALT'};(O/'stage6_rbm6_gtex_cortex_prepare_receipt.json').write_text(json.dumps(rec,indent=2)+'\n');print(rec)
